draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw fox cubs
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';

  // Cub 1
  ctx.beginPath();
  ctx.arc(W/4 + Math.sin(t)*20, H/2 + Math.cos(t)*20, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4 + Math.sin(t)*20, H/2 + Math.cos(t)*20 + 20);
  ctx.lineTo(W/4 + Math.sin(t)*20 - 10, H/2 + Math.cos(t)*20 + 40);
  ctx.lineTo(W/4 + Math.sin(t)*20 + 10, H/2 + Math.cos(t)*20 + 40);
  ctx.stroke();

  // Cub 2
  ctx.beginPath();
  ctx.arc(W/4*3 + Math.sin(t+Math.PI)*20, H/2 + Math.cos(t+Math.PI)*20, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4*3 + Math.sin(t+Math.PI)*20, H/2 + Math.cos(t+Math.PI)*20 + 20);
  ctx.lineTo(W/4*3 + Math.sin(t+Math.PI)*20 - 10, H/2 + Math.cos(t+Math.PI)*20 + 40);
  ctx.lineTo(W/4*3 + Math.sin(t+Math.PI)*20 + 10, H/2 + Math.cos(t+Math.PI)*20 + 40);
  ctx.stroke();

  ctx.restore();
}
